{
  "PROP-0000-create-inv-003": {
    "property_id": "PROP-0000-create-inv-003",
    "audit_result": {
      "property_id": "PROP-0000-create-inv-003",
      "classification": "vulnerability",
      "code_path": "supabase/migrations/0001_create_attendance_schema.sql::policy \"Allow read access for all users\"::L66-67",
      "proof_trace": "The RLS policy 'Allow read access for all users' on attendance.temp_registrations uses USING (true) with no role restriction and no column exclusion, granting the anon role unrestricted SELECT access to all rows including qr_token. The fix migration (20260317000001) preserves and explicitly reinforces this SELECT grant without adding any expiry filter or column-level restriction. Since qr_token is the sole bearer credential for the card-ID-to-user-account linking flow (completeRegistration), and the kiosk Realtime subscription does not require enumerating all tokens (it already knows the token it generated), neither disjunct of the property holds.",
      "attack_scenario": "An unauthenticated attacker sends GET /rest/v1/temp_registrations?select=qr_token,card_id to the Supabase PostgREST endpoint and retrieves all active QR tokens; the attacker then authenticates as any account and visits /register/STOLEN_TOKEN, causing completeRegistration to link their auth identity to the victim's card_id and enabling them to forge attendance records as the victim.",
      "checklist_id": "PROP-0000-create-inv-003"
    },
    "text": "temp_registrations qr_token must not be readable by anon role to prevent token theft.",
    "assertion": "policy(temp_registrations, anon, SELECT).columns NOT INCLUDES qr_token OR policy restricts expired rows",
    "covers": "SG-004",
    "severity": "HIGH",
    "type": "invariant"
  }
}

